const items = $input.all();

return items.map(item => {
  const bKeys = item.binary ? Object.keys(item.binary) : [];
  if (bKeys.length) {
    const realKey = bKeys[0];
    const { data, mimeType, fileName } = item.binary[realKey];

    // determine fileType...
    let fileType = 'unknown';
    if (mimeType.startsWith('image/')) fileType = 'image';
    else if (mimeType === 'application/pdf') fileType = 'pdf';
    item.json.fileType = fileType;
    item.json.mimeType = mimeType;

    // normalize **including** fileName
    item.binary.data0 = { data, mimeType, fileName };
  } else {
    item.json.fileType = 'no_file';
    item.json.mimeType = 'none';
  }
  return item;
});

const item = $input.first();
const input = item.json;

let raw = null;

/* ------------------------------------
   Extract Gemini text (your exact format)
-------------------------------------*/
if (
  input?.content?.parts &&
  Array.isArray(input.content.parts) &&
  typeof input.content.parts[0]?.text === 'string'
) {
  raw = input.content.parts[0].text.trim();
}

if (!raw) {
  // Nothing to parse → pass through safely
  return [{ json: input, binary: item.binary }];
}

/* ------------------------------------
   Parse JSON
-------------------------------------*/
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (err) {
  // Invalid JSON → pass through
  return [{ json: input, binary: item.binary }];
}

/* ------------------------------------
   Check if ALL fields are null / empty
-------------------------------------*/
const fieldsToCheck = [
  'invoice',
  'vendor',
  'date',
  'due_date',
  'description',
  'subtotal',
  'tax',
  'total',
  'email',
  'status',
];

const allNull = fieldsToCheck.every(
  key => parsed[key] === null || parsed[key] === '' || parsed[key] === undefined
);

if (allNull) {
  // ✅ All values are null → pass to next node without modification
  return [{ json: parsed, binary: item.binary }];
}

/* ------------------------------------
   Build markdown ONLY if data exists
-------------------------------------*/
const markdown = `
**Invoice Summary**

- **Invoice #:** ${parsed.invoice || 'N/A'}
- **Vendor:** ${parsed.vendor || 'N/A'}
- **Date:** ${parsed.date || 'N/A'}
- **Due Date:** ${parsed.due_date || 'N/A'}
- **Description:** ${parsed.description || 'N/A'}
- **Subtotal:** $${!isNaN(Number(parsed.subtotal)) ? Number(parsed.subtotal).toFixed(2) : '0.00'}
- **Tax:** $${!isNaN(Number(parsed.tax)) ? Number(parsed.tax).toFixed(2) : '0.00'}
- **Total:** $${!isNaN(Number(parsed.total)) ? Number(parsed.total).toFixed(2) : '0.00'}
- **Status:** ${parsed.status || 'N/A'}
`.trim();

/* ------------------------------------
   Return parsed + markdown
-------------------------------------*/
return [
  {
    json: {
      ...parsed,
      markdown,
    },
    binary: item.binary,
  },
];

